32	/**
33	 * Returns the shared Database instance, creating it (and the required tables)
34	 * on first call. The path is `data/trading.db` relative to `process.cwd()`.
35	 *
36	 * Other modules (db.ts) may also open the same file – SQLite handles this
37	 * correctly via its own locking.  When db.ts lands it can become the single
38	 * owner; until then auth.ts is self-sufficient.
39	 */
40	export function getDb(): Database {
41	  if (_db) return _db;
42	
43	  // Ensure the data directory exists
44	  const dir = join(process.cwd(), "data");
45	  if (!existsSync(dir)) {
46	    mkdirSync(dir, { recursive: true });
47	  }
48	
49	  const db = new Database(join(dir, "trading.db"));
50	  db.exec("PRAGMA journal_mode = WAL");
51	  db.exec("PRAGMA foreign_keys = ON");
52	
53	  // Create tables required by auth (idempotent)
54	  db.exec(`
55	    CREATE TABLE IF NOT EXISTS users (
56	      id INTEGER PRIMARY KEY AUTOINCREMENT,
57	      username TEXT NOT NULL UNIQUE,
58	      password_hash TEXT NOT NULL,
59	      balance REAL NOT NULL DEFAULT 1000000,
60	      created_at INTEGER NOT NULL DEFAULT (unixepoch())
61	    );
62	  `);
63	
64	  db.exec(`
65	    CREATE TABLE IF NOT EXISTS sessions (
66	      token TEXT PRIMARY KEY,
67	      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
68	      created_at INTEGER NOT NULL DEFAULT (unixepoch())
69	    );
70	  `);
71	
72	  _db = db;
73	  return db;
74	}
