85	function generateToken(): string {
86	  const bytes = new Uint8Array(32);
87	  crypto.getRandomValues(bytes);
88	  return Array.from(bytes)
89	    .map((b) => b.toString(16).padStart(2, "0"))
90	    .join("");
91	}
