97	/**
98	 * Hono middleware that validates a Bearer token from the `Authorization`
99	 * header, loads the corresponding user, and stores `userId` + `user` on the
100	 * context variables.  Returns a 401 JSON response on failure.
101	 */
102	export async function authMiddleware(
103	  c: { req: { header: (name: string) => string | undefined }; set: (key: string, value: unknown) => void; json: (body: unknown, status: number) => Response },
104	  next: () => Promise<void>,
105	): Promise<Response | void> {
106	  const header = c.req.header("Authorization");
107	  if (!header || !header.startsWith("Bearer ")) {
108	    return c.json({ error: "Unauthorized" }, 401);
109	  }
110	
111	  const token = header.slice(7);
112	  const db = getDb();
113	
114	  const row = db
115	    .query<{ user_id: number }, [string]>(
116	      "SELECT user_id FROM sessions WHERE token = ?",
117	    )
118	    .get(token);
119	
120	  if (!row) {
121	    return c.json({ error: "Unauthorized" }, 401);
122	  }
123	
124	  const user = db
125	    .query<User, [number]>(
126	      "SELECT id, username, balance, created_at FROM users WHERE id = ?",
127	    )
128	    .get(row.user_id);
129	
130	  if (!user) {
131	    return c.json({ error: "Unauthorized" }, 401);
132	  }
133	
134	  c.set("userId", user.id);
135	  c.set("user", user);
136	  return next();
137	}
