3	/** Box-Muller transform for normal random variable */
4	function randn(): number {
5	  let u = 0,
6	    v = 0;
7	  while (u === 0) u = Math.random();
8	  while (v === 0) v = Math.random();
9	  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
10	}
