92	/**
93	 * Match pending orders against the new market price for a given stock.
94	 */
95	function matchOrders(stockCode: string, marketPrice: number): void {
96	  const pendingOrders = stmtGetPendingOrders.all(stockCode) as OrderRow[];
97	
98	  for (const order of pendingOrders) {
99	    let shouldFill = false;
100	
101	    if (order.direction === "buy" && marketPrice <= order.price) {
102	      shouldFill = true;
103	    } else if (order.direction === "sell" && marketPrice >= order.price) {
104	      shouldFill = true;
105	    }
106	
107	    if (!shouldFill) continue;
108	
109	    const filledPrice = marketPrice;
110	    const totalCost = filledPrice * order.quantity;
111	
112	    if (order.direction === "buy") {
113	      // Check user has enough balance
114	      const user = stmtGetUser.get(order.user_id) as { balance: number } | null;
115	      if (!user || user.balance < totalCost) continue;
116	
117	      // Deduct balance
118	      stmtUpdateBalance.run(round2(user.balance - totalCost), order.user_id);
119	
120	      // Update/create position
121	      const pos = stmtGetPosition.get(order.user_id, stockCode) as PositionRow | null;
122	      if (pos) {
123	        const newQty = pos.quantity + order.quantity;
124	        const newCost = round2(
125	          (pos.cost_basis * pos.quantity + filledPrice * order.quantity) / newQty
126	        );
127	        stmtUpdatePosition.run(newQty, newCost, pos.id);
128	      } else {
129	        stmtInsertPosition.run(order.user_id, stockCode, order.quantity, filledPrice);
130	      }
131	    } else {
132	      // Sell order
133	      const pos = stmtGetPosition.get(order.user_id, stockCode) as PositionRow | null;
134	      if (!pos || pos.quantity < order.quantity) continue;
135	
136	      // Credit balance
137	      const user = stmtGetUser.get(order.user_id) as { balance: number } | null;
138	      if (!user) continue;
139	      stmtUpdateBalance.run(round2(user.balance + totalCost), order.user_id);
140	
141	      // Update position
142	      const newQty = pos.quantity - order.quantity;
143	      if (newQty === 0) {
144	        stmtUpdatePosition.run(0, 0, pos.id);
145	      } else {
146	        stmtUpdatePosition.run(newQty, pos.cost_basis, pos.id);
147	      }
148	    }
149	
150	    // Mark order as filled
151	    stmtFillOrder.run(filledPrice, order.id);
152	
153	    // Update stock volume
154	    stmtUpdateStockVolume.run(order.quantity, stockCode);
155	  }
156	}
