185	/**
186	 * Generate initial historical price points (60 ticks) for all stocks to simulate
187	 * the trading day so far. Called once at startup.
188	 */
189	export function generateInitialHistory(): void {
190	  const stocks = stmtGetAllStocks.all() as StockRow[];
191	  const now = Math.floor(Date.now() / 1000);
192	
193	  db.exec("BEGIN TRANSACTION");
194	  try {
195	    for (const stock of stocks) {
196	      let price = stock.open_price;
197	      let high = stock.open_price;
198	      let low = stock.open_price;
199	      let totalVolume = 0;
200	
201	      for (let i = 0; i < 60; i++) {
202	        const sigma = 0.005;
203	        const randomReturn = randn() * sigma + stock.trend;
204	        price = round2(price * (1 + randomReturn));
205	
206	        const upper = round2(stock.open_price * 1.1);
207	        const lower = round2(stock.open_price * 0.9);
208	        price = Math.max(lower, Math.min(upper, price));
209	
210	        high = Math.max(high, price);
211	        low = Math.min(low, price);
212	
213	        const tickVolume = Math.floor(Math.random() * 5000) + 100;
214	        totalVolume += tickVolume;
215	
216	        // Timestamp spread over the last 120 seconds (2s intervals)
217	        const ts = now - (60 - i) * 2;
218	        db.prepare(
219	          "INSERT INTO price_history (stock_code, price, volume, created_at) VALUES (?, ?, ?, ?)"
220	        ).run(stock.code, price, tickVolume, ts);
221	      }
222	
223	      stmtUpdateStock.run(price, high, low, totalVolume, stock.code);
224	    }
225	    db.exec("COMMIT");
226	  } catch (e) {
227	    db.exec("ROLLBACK");
228	    throw e;
229	  }
