237	/**
238	 * Broadcast current market snapshot to all SSE clients.
239	 */
240	function broadcastSnapshot(): void {
241	  if (sseClients.size === 0) return;
242	  const stocks = stmtGetAllStocks.all() as StockRow[];
243	  const snapshot = stocks.map((s) => ({
244	    code: s.code,
245	    name: s.name,
246	    current_price: s.current_price,
247	    open_price: s.open_price,
248	    high_price: s.high_price,
249	    low_price: s.low_price,
250	    change: round2(s.current_price - s.open_price),
251	    change_percent: round2(((s.current_price - s.open_price) / s.open_price) * 100),
252	    volume: s.volume,
253	  }));
254	  const data = JSON.stringify(snapshot);
255	  for (const send of sseClients) {
256	    try {
257	      send(data);
258	    } catch {
259	      sseClients.delete(send);
260	    }
261	  }
262	}
