95	function matchOrders(stockCode: string, marketPrice: number): void {
96	  const pendingOrders = stmtGetPendingOrders.all(stockCode) as OrderRow[];
97	
98	  for (const order of pendingOrders) {
99	    let shouldFill = false;
100	
101	    if (order.direction === "buy" && marketPrice <= order.price) {
102	      shouldFill = true;
103	    } else if (order.direction === "sell" && marketPrice >= order.price) {
104	      shouldFill = true;
105	    }
106	
107	    if (!shouldFill) continue;
108	
109	    const filledPrice = marketPrice;
110	    const totalCost = filledPrice * order.quantity;
111	
112	    if (order.direction === "buy") {
113	      // Check user has enough balance
114	      const user = stmtGetUser.get(order.user_id) as { balance: number } | null;
115	      if (!user || user.balance < totalCost) continue;
