102	export async function authMiddleware(
103	  c: { req: { header: (name: string) => string | undefined }; set: (key: string, value: unknown) => void; json: (body: unknown, status: number) => Response },
104	  next: () => Promise<void>,
105	): Promise<Response | void> {
106	  const header = c.req.header("Authorization");
107	  if (!header || !header.startsWith("Bearer ")) {
108	    return c.json({ error: "Unauthorized" }, 401);
109	  }
110	
111	  const token = header.slice(7);
112	  const db = getDb();
113	
