75	/**
76	 * Simulate a single tick: update price with random walk + trend, clamp to ±10% of open.
77	 */
78	function simulatePrice(stock: StockRow): number {
79	  const sigma = 0.005; // 0.5% volatility
80	  const randomReturn = randn() * sigma + stock.trend;
81	  let newPrice = stock.current_price * (1 + randomReturn);
82	  newPrice = round2(newPrice);
83	
84	  // Clamp to ±10% of open price
85	  const upper = round2(stock.open_price * 1.1);
86	  const lower = round2(stock.open_price * 0.9);
87	  newPrice = Math.max(lower, Math.min(upper, newPrice));
88	
89	  return newPrice;
90	}
