161	export function tick(): void {
162	  const stocks = stmtGetAllStocks.all() as StockRow[];
163	
164	  db.exec("BEGIN TRANSACTION");
165	  try {
166	    for (const stock of stocks) {
167	      const newPrice = simulatePrice(stock);
168	      const tickVolume = Math.floor(Math.random() * 5000) + 100;
169	      const newHigh = Math.max(stock.high_price, newPrice);
170	      const newLow = Math.min(stock.low_price, newPrice);
171	
172	      stmtUpdateStock.run(newPrice, newHigh, newLow, stock.volume + tickVolume, stock.code);
173	      stmtInsertPriceHistory.run(stock.code, newPrice, tickVolume);
174	
175	      // Match orders at new price
176	      matchOrders(stock.code, newPrice);
177	    }
178	    db.exec("COMMIT");
179	  } catch (e) {
180	    db.exec("ROLLBACK");
181	    throw e;
182	  }
183	}
